import { useProductSearch } from '@salesforce/commerce-sdk-react';

// Types
import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';
import PageContainer from '../../components/pageContainer';

// --- Shared layout ---

type HomepageContentProps = {
  fields: HomepageEntry['fields'];
  entryId: string;
};

const HomepageContent = ({ fields, entryId }: HomepageContentProps) => {
  const intl = useIntl();

  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
    parameters: {
      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  return (
    <>
      {fields.heroBanner && (
        <PageContainer boxed="desktop">
          <HeroBanner heroBanner={fields.heroBanner} entryId={entryId} />
        </PageContainer>
      )}
      {fields.duplexSection && <DuplexSection duplexSection={fields.duplexSection} entryId={entryId} />}
      {fields.videoEmbed && <VideoEmbed videoEmbed={fields.videoEmbed} entryId={entryId} />}
      {fields.productHero && (
        <>
          <Box maxWidth="container.xl" marginX="auto" paddingX={8} paddingTop={12}>
            <Text as="h3" fontSize="2xl" fontWeight="bold" marginBottom={2}>
              Featured Product
            </Text>
          </Box>
          <ProductHero productHero={fields.productHero} entryId={entryId} />
        </>
      )}
      {productSearchResult && (
        // From PWA template - Example on how to show products
        <Section
          padding={4}
          paddingTop={16}
          title={intl.formatMessage({
            defaultMessage: 'Shop Products',
            id: 'home.heading.shop_products',
          })}
          subtitle={intl.formatMessage(
            {
              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
              id: 'home.description.shop_products',
              description:
                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
            },
            {
              docLink: (
                <Link
                  target="_blank"
                  href={'https://sfdc.co/business-manager-manage-catalogs'}
                  textDecoration={'none'}
                  position={'relative'}
                  _after={{
                    position: 'absolute',
                    content: `""`,
                    height: '2px',
                    bottom: '-2px',
                    margin: '0 auto',
                    left: 0,
